import React, { useState } from "react";

const ForgotPassword = () => {
  const [mobile, setMobile] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSendOtp = async () => {
    setLoading(true);
    try {
      const res = await fetch("http://localhost:8080/api/otp/send", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mobile }),
      });

      if (!res.ok) throw new Error("OTP পাঠানো ব্যর্থ হয়েছে");
      setOtpSent(true);
      setMessage("✅ ওটিপি পাঠানো হয়েছে।");
    } catch (err) {
      setMessage("❌ " + err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async () => {
    setLoading(true);
    try {
      const res = await fetch("http://localhost:8080/api/otp/reset-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mobile, otp, newPassword }),
      });

      if (!res.ok) throw new Error("পাসওয়ার্ড রিসেট ব্যর্থ হয়েছে");

      setMessage("✅ পাসওয়ার্ড সফলভাবে রিসেট হয়েছে। এখন লগইন করুন।");
    } catch (err) {
      setMessage("❌ " + err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-100 p-4">
      <div className="bg-white shadow-lg rounded-lg p-6 w-full max-w-md">
        <h2 className="text-2xl font-bold mb-4 text-center text-indigo-600">
          পাসওয়ার্ড ভুলে গেছেন?
        </h2>

        <input
          type="text"
          placeholder="মোবাইল নাম্বার"
          value={mobile}
          onChange={(e) => setMobile(e.target.value)}
          className="w-full mb-3 px-4 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-indigo-500"
        />

        {!otpSent ? (
          <button
            onClick={handleSendOtp}
            disabled={loading || !mobile}
            className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-700 transition"
          >
            {loading ? "পাঠানো হচ্ছে..." : "OTP পাঠান"}
          </button>
        ) : (
          <>
            <input
              type="text"
              placeholder="ওটিপি"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              className="w-full mb-3 px-4 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />

            <input
              type="password"
              placeholder="নতুন পাসওয়ার্ড"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="w-full mb-3 px-4 py-2 border rounded focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />

            <button
              onClick={handleResetPassword}
              disabled={loading || !otp || !newPassword}
              className="w-full bg-green-600 text-white py-2 rounded hover:bg-green-700 transition"
            >
              {loading ? "আপডেট হচ্ছে..." : "পাসওয়ার্ড রিসেট করুন"}
            </button>
          </>
        )}

        {message && (
          <div className="mt-4 text-center text-sm text-red-600">{message}</div>
        )}
      </div>
    </div>
  );
};

export default ForgotPassword;
